using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using System.Reflection;using Frociart;
internal static class CycleUiTests {
 static int checks;static BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
 static void Check(bool v,string s){if(!v)throw new Exception(s);checks++;}static void Pump(int ms){var t=System.Diagnostics.Stopwatch.StartNew();while(t.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(8);}}
 static object Get(object o,string n){return o.GetType().GetField(n,flags).GetValue(o);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,flags).Invoke(o,args);}
 static IEnumerable<Control> Children(Control c){yield return c;foreach(Control n in c.Controls)foreach(var x in Children(n))yield return x;}
 static string Run(Diagram d){var i=new Interpreter(d);for(int x=0;x<500&&i.State!=RuntimeState.Completed&&i.State!=RuntimeState.Error;x++)i.Step();Check(i.State==RuntimeState.Completed,"Executes after UI edit");return String.Join("|",i.Output);}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();UiMotion.SetEnabled(true);typeof(UiMotion).GetField("systemAnimations",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,true);
  using(var main=new MainForm(null,true)){main.Show();Pump(100);foreach(bool dark in new[]{false,true}){Ui.SetDarkMode(dark,false);for(int kind=0;kind<3;kind++){var b=DiagramIO.CreateBlank();var d=FlowLoopBuilder.Prepare(b,null,b.Edges[0].Id,FlowLoopBuilder.Spec.Default(kind)).Project;main.SetDocument(d,null,false);var info=FlowCycle.Find(d).Single();main.Canvas.SelectNode(info.Check);bool opened=false;Exception issue=null;
   using(var timer=new System.Windows.Forms.Timer{Interval=40}){timer.Tick+=delegate{var dialog=Application.OpenForms.OfType<LoopEditorDialog>().FirstOrDefault();if(dialog==null)return;timer.Stop();try{opened=true;Check(dialog.Editing!=null&&!dialog.Kind.Visible&&!dialog.Target.Visible&&!dialog.Body.Visible,"Compact header editor has only relevant fields");Check(dialog.Apply.Text=="Salva ciclo"&&dialog.Apply.Visible,"Save action available");if(kind==0){dialog.Step.Text="0";dialog.Apply.PerformClick();Check(dialog.Visible&&dialog.Error.Text.Length>0,"Invalid step remains recoverable");dialog.Step.Text="1";dialog.To.Text="3";}else dialog.Condition.Text="i < 3";Pump(360);using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(Point.Empty,dialog.Size));image.Save(Path.Combine(args[0],"pc-cycle-editor-"+kind+"-"+dark+".png"));}dialog.Apply.PerformClick();}catch(Exception e){issue=e;dialog.Close();}};timer.Start();((Button)Get(main,"cycleButton")).PerformClick();timer.Stop();}
   if(issue!=null)throw issue;Console.WriteLine("UI_OPEN kind="+kind+" opened="+opened+" button="+((Button)Get(main,"cycleButton")).Visible+" selected="+main.Canvas.SelectedNodeId+" output="+Run(main.Project));Check(opened&&Run(main.Project)==(kind==0?"1|2|3":"0|1|2"),"Real inspector action edits cycle "+kind);int beforeUndo=((System.Collections.ICollection)Get(main,"undo")).Count;Check(beforeUndo==1,"Real UI saves cycle as one undo step");main.Canvas.SelectNode(info.Check);
   using(var timer=new System.Windows.Forms.Timer{Interval=40}){timer.Tick+=delegate{var dialog=Application.OpenForms.OfType<LoopEditorDialog>().FirstOrDefault();if(dialog==null)return;timer.Stop();Children(dialog).OfType<Button>().Single(c=>c.Text=="Seleziona ciclo").PerformClick();};timer.Start();((Button)Get(main,"cycleButton")).PerformClick();timer.Stop();}Check(main.Canvas.SelectionCount==info.Members.Count,"Cycle group selection exact");Check(((System.Collections.ICollection)Get(main,"undo")).Count==beforeUndo,"Selecting group creates no undo mutation");
  }}
  main.SetDocument(DiagramIO.CreateBlank(),null,false);using(var list=new CycleListDialog(FlowCycle.Find(main.Document))){list.Show();Pump(80);Check(Children(list).OfType<Label>().Any(c=>c.Text.Contains("Non ci sono cicli")),"Empty state explains recovery");list.Close();}
  foreach(int kind in new[]{0,1,2})Check(Run(DiagramIO.Load(Path.Combine(args[0],"android-cycle-"+kind+".frociart")))==(kind==0?"1|2|3":"0|1|2"),"Android saved cycle runs on PC");main.SetDocument(new Diagram(),null,false);main.Close();}
  Console.WriteLine("CYCLE_UI_PC PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
